## alphabet with space
alphabet = c(LETTERS, " ")

## decode: replace ciphertext with mapping

decode = function(mapping, coded) {
  coded = toupper(coded)
  decoded = coded
  for (i in 1:nchar(coded)) {
      substring(decoded, i, i) = alphabet[mapping == substring(coded, i, i)]
  }
  decoded
}

